<?php declare(strict_types=1); namespace App\Models\Pmbm; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; class PmbmApplicantDocument extends Model {protected $guarded=[]; protected function casts():array{return ['is_current'=>'boolean'];} public function applicant():BelongsTo{return $this->belongsTo(PmbmApplicant::class,'applicant_id');} public function verifiedBy():BelongsTo{return $this->belongsTo(\App\Models\User::class,'verified_by');} public function replacedDocument():BelongsTo{return $this->belongsTo(self::class,'replaces_document_id');}}
